def deliver_weekly_orders_report(run_at_utc: str | None = None) -> dict:
    """Validate, compute, and deliver the scheduled weekly orders report.

    Uses the task's fixed local metrics API at http://127.0.0.1:8123. When
    ``run_at_utc`` is omitted, the current UTC runtime supplies the run date;
    callers may pass an ISO-8601 timestamp for deterministic replay/testing.
    The function fetches the last full Monday-Sunday week and its predecessor,
    validates every required order field before any POST, computes revenue in
    integer cents, rejects an undefined zero-baseline comparison, and returns
    the delivered report plus HTTP response metadata.
    """
    import json
    import logging
    import re
    from datetime import datetime, timedelta, timezone
    from urllib.parse import urlencode
    from urllib.request import Request, urlopen

    logger = logging.getLogger(__name__)
    base_url = "http://127.0.0.1:8123"
    required_fields = {
        "order_id", "date", "region", "units", "unit_price_cents"
    }
    report_keys = (
        "week_start",
        "week_end",
        "total_units",
        "total_revenue_cents",
        "revenue_by_region_cents",
        "wow_revenue_change_pct",
    )

    def parse_run_time(value):
        if value is None:
            return datetime.now(timezone.utc)
        if not isinstance(value, str):
            raise TypeError("run_at_utc must be an ISO-8601 string or None")
        try:
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValueError(f"run_at_utc is not valid ISO-8601: {value}") from exc
        if parsed.tzinfo is None:
            raise ValueError("run_at_utc must include a timezone offset")
        return parsed.astimezone(timezone.utc)

    def fetch_orders(start_date, end_date):
        params = urlencode({
            "start": start_date.isoformat(),
            "end": end_date.isoformat(),
        })
        url = f"{base_url}/orders?{params}"
        logger.info("PHASE GET orders start=%s end=%s", start_date, end_date)
        request = Request(
            url,
            method="GET",
            headers={"Accept": "application/json"},
        )
        with urlopen(request, timeout=15) as response:
            raw = response.read()
            status = response.status
        if not 200 <= status < 300:
            raise RuntimeError(f"GET {url} failed with HTTP {status}")
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ValueError(f"GET {url} did not return valid JSON: {exc}") from exc
        if not isinstance(data, list):
            raise TypeError(
                f"GET {url} returned {type(data).__name__}, expected a JSON list"
            )
        return data

    def validate_orders(orders, start_date, end_date, label):
        validated = []
        for index, order in enumerate(orders):
            where = f"{label} order index {index}"
            if not isinstance(order, dict):
                raise TypeError(
                    f"{where} is {type(order).__name__}, expected object"
                )
            missing = sorted(required_fields - order.keys())
            if missing:
                raise ValueError(f"{where} is missing required fields: {missing}")
            if order["order_id"] is None or isinstance(
                order["order_id"], (dict, list)
            ):
                raise TypeError(f"{where}.order_id must be a non-null scalar")
            date_text = order["date"]
            if not isinstance(date_text, str) or not re.fullmatch(
                r"\d{4}-\d{2}-\d{2}", date_text
            ):
                raise TypeError(f"{where}.date must be a YYYY-MM-DD string")
            try:
                order_date = datetime.strptime(date_text, "%Y-%m-%d").date()
            except ValueError as exc:
                raise ValueError(
                    f"{where}.date is not a valid calendar date: {date_text}"
                ) from exc
            if not start_date <= order_date <= end_date:
                raise ValueError(
                    f"{where}.date {order_date} is outside requested range "
                    f"{start_date}..{end_date}"
                )
            region = order["region"]
            if not isinstance(region, str) or not region:
                raise TypeError(f"{where}.region must be a non-empty string")
            units = order["units"]
            unit_price_cents = order["unit_price_cents"]
            if isinstance(units, bool) or not isinstance(units, int):
                raise TypeError(f"{where}.units must be an integer")
            if isinstance(unit_price_cents, bool) or not isinstance(
                unit_price_cents, int
            ):
                raise TypeError(
                    f"{where}.unit_price_cents must be an integer"
                )
            validated.append(order)
        logger.info("PHASE VALIDATED %s rows=%d", label, len(validated))
        return validated

    def revenue_cents(orders):
        return sum(
            order["units"] * order["unit_price_cents"] for order in orders
        )

    try:
        run_at = parse_run_time(run_at_utc)
        run_date = run_at.date()
        report_end = run_date - timedelta(days=run_date.weekday() + 1)
        report_start = report_end - timedelta(days=6)
        previous_end = report_start - timedelta(days=1)
        previous_start = previous_end - timedelta(days=6)
        logger.info(
            "PHASE DATE_WINDOW run_date_utc=%s report=%s..%s previous=%s..%s",
            run_date,
            report_start,
            report_end,
            previous_start,
            previous_end,
        )

        current_raw = fetch_orders(report_start, report_end)
        previous_raw = fetch_orders(previous_start, previous_end)
        current = validate_orders(
            current_raw, report_start, report_end, "report week"
        )
        previous = validate_orders(
            previous_raw, previous_start, previous_end, "previous week"
        )

        current_revenue = revenue_cents(current)
        previous_revenue = revenue_cents(previous)
        if previous_revenue == 0:
            logger.error(
                "SOFT_FAIL previous-week total_revenue_cents is zero; "
                "wow formula is undefined; report not posted"
            )
            raise RuntimeError(
                "Previous-week total_revenue_cents is zero; "
                "wow_revenue_change_pct is undefined. Report was not posted."
            )

        revenue_by_region = {}
        for order in current:
            region = order["region"]
            revenue_by_region[region] = revenue_by_region.get(region, 0) + (
                order["units"] * order["unit_price_cents"]
            )

        payload = {
            "week_start": report_start.isoformat(),
            "week_end": report_end.isoformat(),
            "total_units": sum(order["units"] for order in current),
            "total_revenue_cents": current_revenue,
            "revenue_by_region_cents": revenue_by_region,
            "wow_revenue_change_pct": round(
                (current_revenue - previous_revenue)
                / previous_revenue
                * 100,
                2,
            ),
        }
        if tuple(payload) != report_keys:
            raise AssertionError("Report payload key contract violated")

        logger.info(
            "PHASE POST report week=%s..%s current_revenue=%d "
            "previous_revenue=%d",
            report_start,
            report_end,
            current_revenue,
            previous_revenue,
        )
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        request = Request(
            f"{base_url}/report",
            data=body,
            method="POST",
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )
        with urlopen(request, timeout=15) as response:
            response_body = response.read().decode("utf-8", errors="replace")
            response_status = response.status
        if not 200 <= response_status < 300:
            raise RuntimeError(
                f"POST /report failed with HTTP {response_status}: "
                f"{response_body}"
            )
        logger.info(
            "PHASE COMPLETE report delivered status=%d", response_status
        )
        return {
            "status": "delivered",
            "http_status": response_status,
            "report": payload,
            "server_response": response_body,
        }
    except Exception as exc:
        logger.error("SOFT_FAIL weekly orders report aborted: %s", exc)
        raise
